function renderLocalControls(){const host=$('#local-speech-controls');if(!host)return;const s=state.settings,engine=s.localEngine||'qwen3',m=localStatus?.models?.[engine];
 host.innerHTML=`<label>Local model<select id="local-engine">${options([['qwen3','Qwen3 · Fast clone (0.6B · 4-bit)'],['qwen3-hq','Qwen3 · Quality clone (1.7B · 8-bit)'],['kokoro','Kokoro · Preset voices']],engine)}</select></label>${engine==='kokoro'?`<label>Preset voice<select id="local-voice">${options(Object.entries(m?.voices||{}),s.localVoice||'af_heart')}</select></label>`:'<p class="note">Uses your twin’s voice recording (3–30 seconds) and its exact transcript. Add both in Edit twin.</p>'}<p class="note">${!localStatus?'Checking local models…':!localStatus.supported?'Requires an Apple Silicon Mac.':!m?.ready?'Download this model in Settings → Local speech.':'Runs on this Mac. No speech API credits.'}</p>${m?`<p class="note">Languages: ${escape(Object.values(m.languages).join(', '))}</p>`:''}`;
 const controls={speed:1,sentencePause:0,volume:1,...state.settings.localSpeech};
 const specs=[['speed','Speed',.75,1.5,.05],['sentencePause','Extra sentence pause',0,2,.1],['volume','Volume',0,2,.05]];
 const format=(key,value)=>key==='speed'?`${Number(value).toFixed(2)}×`:key==='volume'?`${Math.round(value*100)}%`:value===0?'Natural':`+${Number(value).toFixed(1)} sec`;
 host.insertAdjacentHTML('beforeend',`<div class="delivery-controls">${specs.map(([key,label,min,max,step])=>`<label for="speech-${key}">${label} <output id="speech-${key}-value">${format(key,controls[key])}</output><input id="speech-${key}" type="range" min="${min}" max="${max}" step="${step}" value="${controls[key]}"></label>`).join('')}<p class="note">Applies to new takes and exported audio. Speed preserves pitch. Volume boosts are limited to prevent clipping.</p><button type="button" class="small subtle" id="reset-speech">Reset delivery</button></div>`);
 for(const [key] of specs){const input=$('#speech-'+key);input.oninput=()=>{controls[key]=Number(input.value);state.settings.localSpeech={...controls};$('#speech-'+key+'-value').textContent=format(key,controls[key]);};input.onchange=()=>action(()=>api('/settings','PUT',{localSpeech:{...controls}}));}
 $('#reset-speech').onclick=()=>action(async()=>{state.settings.localSpeech={speed:1,sentencePause:0,volume:1};await api('/settings','PUT',{localSpeech:state.settings.localSpeech});renderLocalControls();});
 $('#local-engine').onchange=e=>action(async()=>{state.settings.localEngine=e.target.value;await api('/settings','PUT',{localEngine:e.target.value});renderLocalControls();renderClipStatus();});
 if($('#local-voice'))$('#local-voice').onchange=e=>action(async()=>{state.settings.localVoice=e.target.value;await api('/settings','PUT',{localVoice:e.target.value});renderClipStatus();});
 if(!localStatus)loadLocalStatus().then(()=>{renderLocalControls();renderClipStatus();}).catch(e=>{host.textContent=e.message;});
}
function renderLocalSettings(){const host=$('#local-tts-settings');if(!host)return;
 if(!localStatus){host.textContent='Checking local speech…';loadLocalStatus().then(renderLocalSettings).catch(e=>{host.textContent=e.message;});return;}
 host.innerHTML=`<p class="note">Qwen3 voice cloning and Kokoro preset voices run inside MyTwin on your Mac. Download each model once. Setup includes an isolated runtime and may take several minutes and several GB of disk space.</p>${!localStatus.supported?'<p>Requires an Apple Silicon Mac.</p>':Object.entries(localStatus.models).map(([key,m])=>`<div class="take-actions"><span>${escape(m.name)} · ${m.ready?'Ready':'Not downloaded'}</span><button type="button" data-local-download="${key}" ${localStatus.busy?'disabled':''}>${m.ready?'Verify / repair':'Download'}</button></div>`).join('')}<p class="note" role="status">${localStatus.busy?'Setting up '+escape(localStatus.engine)+'… Keep MyTwin open.':''}</p>${localStatus.error?`<p class="error">${escape(localStatus.error)}</p>`:''}<button type="button" id="refresh-local">Refresh status</button>`;
 host.querySelectorAll('[data-local-download]').forEach(b=>b.onclick=()=>action(async()=>{await api('/local-tts/download','POST',{engine:b.dataset.localDownload});await loadLocalStatus();renderLocalSettings();}));$('#refresh-local').onclick=()=>action(async()=>{await loadLocalStatus();renderLocalSettings();});
}
setInterval(()=>{if(localStatus?.busy){const before=JSON.stringify(localStatus);loadLocalStatus().then(()=>{if(JSON.stringify(localStatus)!==before){renderLocalSettings();renderLocalControls();renderClipStatus();}}).catch(()=>{});}},3000);
function renderSpeechControls(){const host=$('#speech-controls');if(!host)return;const s=state.settings,model=s.speechModel||'',m=modelsFor('speech').find(x=>x.id===model),details=speechDetails[model];
 host.innerHTML=`<div class="fields">${modelPicker('speech',model,'speech-model','speechModel','Speech model')}<label>Voice<select id="voice-mode">${options([['clone','My voice'],['preset','Preset voice']],s.voiceMode||'clone')}</select></label></div><div id="speech-voice"></div><p class="note" id="speech-note"></p>`;
 const update=()=>{const mode=$('#voice-mode').value,voices=(m?.voices||[]).filter(v=>typeof v==='string');$('#speech-voice').innerHTML=mode==='preset'?`<label>Preset voice<select id="preset-voice">${options([['','Choose a voice'],...voices.map(v=>[v,v])],s.voice||'')}</select></label>`:'';
 $('#speech-note').textContent=!model?'Choose a speech model.':mode==='clone'?(details?details.cloning?'Sends your script and voice sample to OpenRouter. Uses credits.':'This model cannot clone your voice. Choose a preset or another model.':'Checking voice support…'):'Sends your script to OpenRouter. Uses credits.';
 if($('#preset-voice'))$('#preset-voice').onchange=e=>{state.settings.voice=e.target.value;action(()=>api('/settings','PUT',{voice:e.target.value}));if($('#prepare'))$('#prepare').disabled=!e.target.value;};
 if($('#prepare'))$('#prepare').disabled=!model||(mode==='clone'&&details?.cloning!==true)||(mode==='preset'&&!$('#preset-voice')?.value);
 };
 initModelPickers();
 $('#speech-model').onchange=e=>action(async()=>{state.settings.speechModel=e.target.value;state.settings.voice='';await api('/settings','PUT',{speechModel:e.target.value,voice:''});renderSpeechControls();});
 $('#voice-mode').onchange=e=>{state.settings.voiceMode=e.target.value;action(()=>api('/settings','PUT',{voiceMode:e.target.value}));update();};update();
 if(model&&!details)loadSpeechDetails(model).then(()=>{if($('#speech-model')?.value===model)renderSpeechControls();}).catch(e=>{if($('#speech-note'))$('#speech-note').textContent=e.message;});
}

let avatarVideoSettings={aspect_ratio:'16:9',resolution:'720p'};
