setInterval(()=>{if(document.hidden||!state||polling)return;polling=true;action(async()=>{try{const before=JSON.stringify(state.jobs);await refresh();if(view==='studio')renderTakes();else if(view==='queue'&&JSON.stringify(state.jobs)!==before)renderQueue();}finally{polling=false;}});},5000);

if(native){const win=window.__TAURI__.window.getCurrentWindow();await win.onCloseRequested(async event=>{if(dirty){event.preventDefault();await action(async()=>{await save();await win.destroy();});}});}
